const DEFAULT_RATE_LIMIT_WINDOW_MS = 60_000;

export function getClientIp(headers: Headers): string {
  const forwardedFor = headers.get("x-forwarded-for");

  if (forwardedFor) {
    return forwardedFor.split(",")[0]?.trim() || "unknown";
  }

  const realIp = headers.get("x-real-ip");
  if (realIp) {
    return realIp;
  }

  const cloudflareIp = headers.get("cf-connecting-ip");
  if (cloudflareIp) {
    return cloudflareIp;
  }

  return "unknown";
}

export class RateLimiter {
  private readonly buckets = new Map<string, { count: number; resetAt: number }>();

  constructor(
    private readonly maxRequests: number,
    private readonly windowMs: number = DEFAULT_RATE_LIMIT_WINDOW_MS,
  ) {}

  isAllowed(key: string, headers: Headers): boolean {
    const now = Date.now();
    const clientIp = getClientIp(headers);
    const bucketKey = `${key}:${clientIp}`;
    const existingBucket = this.buckets.get(bucketKey);

    if (!existingBucket || existingBucket.resetAt <= now) {
      this.buckets.set(bucketKey, { count: 1, resetAt: now + this.windowMs });
      return true;
    }

    if (existingBucket.count >= this.maxRequests) {
      return false;
    }

    existingBucket.count += 1;
    return true;
  }
}

export function isSafeRedirectUrl(value: string): boolean {
  const candidate = value.trim();

  if (!candidate) {
    return false;
  }

  let parsedUrl: URL;

  try {
    parsedUrl = new URL(candidate);
  } catch {
    return false;
  }

  if (!["http:", "https:"].includes(parsedUrl.protocol)) {
    return false;
  }

  if (parsedUrl.username || parsedUrl.password) {
    return false;
  }

  return true;
}

export function normalizeSafeRedirectUrl(value: string): string | null {
  if (!isSafeRedirectUrl(value)) {
    return null;
  }

  return new URL(value.trim()).toString();
}
